import {confirmButtonResult} from './button-feedback.js';
import {MISSION_TYPES,MISSION_TIERS,missionList,missionOffers,missionOdds,missionReward} from './missions.js';
import {missionSlots,nextMissionSlot,buildingLevel,buildingUpgrade} from './village.js';
import {RECORDS} from './records.js';
import {PET_CATALOG} from './home-collection.js';
import {questRecordCandidates} from './mission-rewards.js';
import {MISSION_ART as ART} from './approved-missions-assets.js';
import {serviceShadow} from './approved-service-host.js';
import {registerMissionPresentation} from './approved-missions-access.js';
export function mountApprovedMissions(dialog,state,{initialUi={},onUiState=()=>{},onAccept,onClaim,onAbandon,onUpgrade,onReceiptDone,onBoard=()=>{},onClose,onCommand=()=>{},softMode=()=>false}){
 const shadow=serviceShadow(dialog,`<div id="gv-missions-service"><div class="scene"><section class="window" id="gm-window" aria-label="Missões do Refúgio">
      <header class="head"><img id="gm-emblem" alt="" draggable="false"><h2>Missões</h2><div class="wallet" aria-label="Moedas disponíveis"><img id="gm-coin" alt="Moedas"><span id="gm-bank"></span></div><button type="button" class="button close cursor-interaction" id="gm-close" aria-label="Fechar Missões">×</button></header>
      <div class="rail"><span class="level" id="gm-level"></span><button type="button" class="button compact cursor-interaction" id="gm-upgrade-open">Melhorar</button><span class="next-slot" id="gm-next"></span><button type="button" class="button compact help-trigger cursor-interaction" id="gm-help" aria-label="Chances e regras">?</button></div>
      <div class="area-tabs" role="tablist" aria-label="Grupos de missões"><button type="button" class="button cursor-interaction" role="tab" id="gm-area-active" data-area="active" aria-controls="gm-active-column" aria-selected="true">Suas missões</button><button type="button" class="button cursor-interaction" role="tab" id="gm-area-offers" data-area="offers" aria-controls="gm-offers-column" aria-selected="false">Ofertas</button></div>
      <div class="workspace" id="gm-workspace">
        <div class="board" id="gm-board">
          <section class="column is-area" id="gm-active-column" aria-label="Suas missões"><header class="section-head"><h3>Suas missões</h3><span id="gm-capacity"></span></header><div class="cards" id="gm-active"></div><nav class="pager" id="gm-active-pages" aria-label="Páginas de missões aceitas"></nav></section>
          <section class="column" id="gm-offers-column" aria-label="Ofertas"><header class="section-head"><h3>Ofertas</h3><span id="gm-offer-total"></span></header><div class="cards offer-cards" id="gm-offers"></div><nav class="pager" id="gm-offer-pages" aria-label="Páginas de ofertas"></nav></section>
        </div>
        <div class="overlay" id="gm-overlay" hidden></div>
        <section class="receipt" id="gm-receipt" aria-label="Recompensa recebida" hidden></section>
      </div>
      <div class="footnotes"><span>◷ Prazo só na caverna</span><span><img id="gm-record" alt="" draggable="false">Gemas e prêmios conforme a oferta</span></div>
      <div class="live" id="gm-live" aria-live="polite"></div>
    </section>
    </div></div>`),css=dialog.ownerDocument.createElement('link');css.rel='stylesheet';css.href='approved-missions-ui.css';shadow.prepend(css);
 const root=shadow.querySelector('#gv-missions-service'),REC={RECORDS},softQuery=matchMedia('(prefers-reduced-motion:reduce)');
 let activePage=Math.max(0,Math.min(2,initialUi.activePage||0)),offerPage=Math.max(0,Math.min(5,initialUi.offerPage||0)),activeCapacity=2,offerCapacity=2,area=['active','offers'].includes(initialUi.area)?initialUi.area:missionList(state).length?'active':'offers',overlay=null,receipt=null,busy=false,disposed=false;
 const remember=()=>onUiState({activePage,offerPage,area});
 const confirmed=(ok,kind)=>{if(ok)confirmButtonResult(root.ownerDocument,kind);return ok;};
 const acceptMission=(_s,id)=>confirmed(onAccept(id),'set'),claimMission=(_s,id)=>confirmed(onClaim(id),'craft'),abandonMission=(_s,id)=>confirmed(onAbandon(id),'unset'),upgradeBuilding=()=>confirmed(onUpgrade(),'building');
const q=s=>root.querySelector(s),all=s=>[...root.querySelectorAll(s)],fmt=n=>Math.floor(n).toLocaleString('pt-BR');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const def=m=>MISSION_TYPES.find(d=>d.id===m.template),title=s=>s.charAt(0)+s.slice(1).toLocaleLowerCase('pt-BR');
const families={miner:'crystals',quartz:'quartz',prism:'ruby',geode:'topaz',vital:'emerald',rocks:'rocks',brute:'rocks',hunter:'slime',slime:'slime',guardians:'golem',bats:'bat',beats:'music',combo:'music',points:'trophy',items:'pulse-potion',bombs:'bomb',cures:'pulse-potion',floors:'stairs-floors',depth4:'stairs-floors',depth8:'stairs-floors'};
const time=m=>{const sec=Math.ceil(m.remaining),minutes=Math.floor(sec/60);return sec>=3600?Math.floor(minutes/60)+'h '+String(minutes%60).padStart(2,'0')+'min':minutes+':'+String(sec%60).padStart(2,'0');};
const objective=m=>{const verb=def(m).verb;if(/^(Quebre|Derrote|Acerte|Ganhe|Complete|Use) /.test(verb)){const i=verb.indexOf(' ');return esc(verb.slice(0,i))+' '+fmt(m.goal)+' '+esc(verb.slice(i+1));}return esc(verb)+' '+fmt(m.goal);};
const img=(key,cls='')=>'<img class="'+cls+'" src="'+esc(ART[key])+'" alt="" draggable="false">';
const materialKeys=['quartz','ruby','topaz','emerald'],materialNames=['Quartzo','Rubi','Topázio','Esmeralda'];
const rewardMarkup=r=>'<div class="quest-rewards"><span class="reward" aria-label="'+fmt(r.gems)+' moedas">'+img('coin')+'+'+fmt(r.gems)+'</span>'+(r.materials||[]).map((n,i)=>n?'<span class="reward mineral" aria-label="'+fmt(n)+' '+materialNames[i]+'">'+img(materialKeys[i])+'+'+fmt(n)+'</span>':'').join('')+'</div>';
const percent=n=>(n*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%';
function bonusMarkup(m){const r=missionReward(m),parts=[];if(r.recordChance>0)parts.push(questRecordCandidates(state).length?'Disco inédito · '+percent(r.recordChance):'Discos disponíveis já encontrados');if(r.petChance>0)parts.push(state.homeCollection?.pets?.includes('bolota')?'Bolota já encontrado':'Bolota · '+percent(r.petChance));return parts.length?'<small class="quest-bonus">'+parts.join(' · ')+'</small>':'';}
const button=(label,attrs='',cls='')=>'<button type="button" class="button cursor-interaction '+cls+'" '+attrs+'>'+label+'</button>';
function syncSoft(){root.dataset.soft=String(softMode()||softQuery.matches);}
function announce(text){q('#gm-live').textContent=text;}
function pulse(selector){if(root.dataset.soft==='true')return;all(selector).forEach(e=>{e.classList.remove('pop');void e.offsetWidth;e.classList.add('pop');e.addEventListener('animationend',()=>e.classList.remove('pop'),{once:true});});}
function pages(kind,page,count){const total=Math.max(1,Math.ceil(count/(kind==='active'?activeCapacity:offerCapacity)));return total<=1?'':button('‹','data-page="'+kind+'" data-step="-1" aria-label="Página anterior de '+(kind==='active'?'missões':'ofertas')+'" '+(page===0?'disabled':''))+'<span>'+(page+1)+'/'+total+'</span>'+button('›','data-page="'+kind+'" data-step="1" aria-label="Próxima página de '+(kind==='active'?'missões':'ofertas')+'" '+(page>=total-1?'disabled':''));}
function missionCard(m,accepted){const d=def(m),ready=accepted&&m.status==='ready',expired=accepted&&m.status==='expired',ratio=100*m.progress/m.goal;
 const progress=accepted?'<div class="progress-row"><div class="track" role="progressbar" aria-label="'+esc(d.name)+'" aria-valuemin="0" aria-valuemax="'+m.goal+'" aria-valuenow="'+m.progress+'"><span data-fill="'+esc(m.id)+'" style="width:'+ratio+'%"></span></div><b>'+fmt(m.progress)+'/'+fmt(m.goal)+'</b></div>':'<div class="card-meta" aria-label="Prazo de exploração">◷ '+time(m)+'</div>';
 const action=!accepted?button('Aceitar','data-mission="'+esc(encodeURIComponent(m.id))+'" data-accept="'+esc(m.id)+'" aria-label="Aceitar: '+esc(objective(m))+'"','primary'):ready?button('Receber','data-claim-mission="'+esc(encodeURIComponent(m.id))+'" data-claim="'+esc(m.id)+'" aria-label="Receber: '+esc(d.name)+'"','primary'):expired?button('Limpar','data-abandon-mission="'+esc(encodeURIComponent(m.id))+'" data-clear="'+esc(m.id)+'"'):'<div class="action-options"><span class="time" aria-label="Prazo pausado no refúgio">⏸ '+time(m)+'</span>'+button('⋯','data-options="'+esc(m.id)+'" aria-label="Opções de '+esc(d.name)+'"','dots')+'</div>';
 return '<article class="mission-card '+(accepted?'accepted':'')+'" data-mission-id="'+esc(m.id)+'" data-tier="'+esc(m.tier)+'" data-status="'+(accepted?esc(m.status):'offer')+'"><div class="mission-main"><div class="face">'+img(families[m.template])+'<div><div class="tier">'+title(MISSION_TIERS[m.tier].name)+' · Nv. '+fmt(m.rewardLevel||1)+(expired?' · Encerrada':'')+'</div><h3>'+(accepted?esc(d.verb):objective(m))+'</h3></div></div>'+progress+bonusMarkup(m)+'</div><div class="card-actions">'+rewardMarkup(missionReward(m))+action+'</div></article>';
}

function getActive(){const order={ready:0,active:1,expired:2};return missionList(state).sort((a,b)=>order[a.status]-order[b.status]);}
function getOffers(){const occupied=new Set(missionList(state).filter(m=>m.status!=='expired').map(m=>m.template));return missionOffers(state).filter(m=>!occupied.has(m.template));}
function renderBoard(animate=false){const old=new Map(all('[data-fill]').map(e=>[e.dataset.fill,(e.parentElement.clientWidth?100*e.getBoundingClientRect().width/e.parentElement.clientWidth:0)+'%']));const active=getActive(),used=active.filter(m=>m.status!=='expired').length,slots=missionSlots(state),offers=getOffers();activePage=Math.min(activePage,Math.max(0,Math.ceil(active.length/activeCapacity)-1));offerPage=Math.min(offerPage,Math.max(0,Math.ceil(offers.length/offerCapacity)-1));
 q('#gm-capacity').textContent=used+'/'+slots;q('#gm-capacity').setAttribute('aria-label',used+' missões em '+slots+' vagas');q('#gm-offer-total').textContent=used<slots?String(offers.length):'';
 q('#gm-active').innerHTML=active.length?active.slice(activePage*activeCapacity,activePage*activeCapacity+activeCapacity).map(m=>missionCard(m,true)).join(''):'<div class="empty">'+img('missions-scroll-summary')+'<h3>'+slots+(slots===1?' vaga livre':' vagas livres')+'</h3><p>Escolha uma oferta.</p></div>';
 q('#gm-offers').innerHTML=used>=slots?'<div class="empty">'+img('missions-scroll-summary')+'<h3>Vagas cheias</h3><p>Entregue ou abandone uma missão.</p></div>':offers.length?offers.slice(offerPage*offerCapacity,offerPage*offerCapacity+offerCapacity).map(m=>missionCard(m,false)).join(''):'<div class="empty"><h3>Sem ofertas</h3></div>';
 q('#gm-active-pages').innerHTML=pages('active',activePage,active.length);q('#gm-offer-pages').innerHTML=used<slots?pages('offers',offerPage,offers.length):'';
 if(animate&&root.dataset.soft!=='true')all('[data-fill]').forEach(e=>{const next=e.style.width,previous=old.get(e.dataset.fill);if(previous&&previous!==next){e.style.width=previous;void e.offsetWidth;requestAnimationFrame(()=>{e.style.width=next;});}});
}
function renderArea(){all('[data-area]').forEach(e=>e.setAttribute('aria-selected',String(e.dataset.area===area)));q('#gm-active-column').classList.toggle('is-area',area==='active');q('#gm-offers-column').classList.toggle('is-area',area==='offers');}
function renderReceipt(){const r=receipt;q('#gm-receipt').innerHTML=!r?'':'<h3>Recompensa recebida!</h3>'+rewardMarkup(r)+(r.record?'<div class="record-found">'+img('record-'+r.record.id)+'<div><small>♫ Disco encontrado</small><strong>'+esc(r.record.name)+'</strong></div></div>':'')+(r.pets||[]).map(p=>'<div class="record-found">'+(p.id==='bolota'?'<img src="assets/pets-companions-v2/bolota/presentation/pose.png" alt="" draggable="false">':'')+'<div><small>Companheiro encontrado</small><strong>'+esc(p.name)+'</strong><span>Disponível na Cuidadora</span></div></div>').join('')+'<div class="receipt-actions">'+button('Continuar','id="gm-receipt-done"','primary')+button('Missões','id="gm-receipt-more"')+'</div>';}
function render(){syncSoft();q('#gm-emblem').src=ART['missions-scroll-header'];q('#gm-coin').src=ART.coin;q('#gm-record').src=ART['rare-record'];q('#gm-bank').textContent=fmt(state.bank);const lv=buildingLevel(state,'missions'),next=nextMissionSlot(state);q('#gm-level').textContent='Quadro · Nv. '+lv;q('#gm-next').textContent=next?'+1 vaga · Nv. '+next:'5 vagas liberadas';q('#gm-upgrade-open').disabled=lv>=150;q('#gm-upgrade-open').textContent=lv>=150?'Máximo':'Melhorar';q('#gm-board').hidden=!!receipt;q('#gm-receipt').hidden=!receipt;q('#gm-upgrade-open').disabled=lv>=150||!!receipt;renderBoard();renderArea();renderReceipt();renderOverlay();}
function renderOverlay(){const el=q('#gm-overlay');el.hidden=!overlay;q('#gm-receipt').inert=!!overlay;if(!overlay){el.innerHTML='';q('#gm-board').inert=false;return;}q('#gm-board').inert=true;const head=heading=>'<header class="overlay-head"><h3>'+heading+'</h3>'+button('×','id="gm-overlay-close" aria-label="Voltar às Missões"','close')+'</header>';
 if(overlay==='upgrade'){const u=buildingUpgrade(state,'missions'),next=structuredClone(state);next.village.missions=Math.min(150,u.level+1);const slots=missionSlots(state),nextSlots=missionSlots(next),costs=[{id:'coin',name:'Moedas',owned:state.bank,cost:u.cost},...u.recipe.map((cost,i)=>({id:['quartz','ruby','topaz','emerald'][i],name:['Quartzo','Rubi','Topázio','Esmeralda'][i],owned:state.materials[i],cost}))];el.innerHTML=head('Quadro '+u.level+' → '+(u.level+1))+'<div class="overlay-inner"><div class="upgrade-summary"><span>Recompensas maiores · Nv. '+(u.level+1)+'</span><span>'+(nextSlots>slots?slots+' → '+nextSlots+' vagas':slots+' vagas')+'</span></div><div class="needs">'+costs.map(c=>'<div class="need '+(c.owned>=c.cost?'done':'')+'" aria-label="'+c.name+': '+fmt(c.owned)+' disponíveis; '+fmt(c.cost)+' necessários">'+img(c.id)+'<div class="track" role="progressbar" aria-label="'+c.name+' para a melhoria" aria-valuemin="0" aria-valuemax="'+c.cost+'" aria-valuenow="'+Math.min(c.owned,c.cost)+'"><span style="width:'+Math.min(100,100*c.owned/c.cost)+'%"></span></div><b>'+fmt(c.owned)+'/'+fmt(c.cost)+'</b></div>').join('')+'</div><p class="pay-note">Pago ao concluir · missões aceitas mantêm seus valores.</p><div class="upgrade-end">'+button('Concluir','id="gm-upgrade-confirm" data-building="missions" '+(u.ready?'':'disabled'),'primary')+'<span class="failure">'+(u.ready?'':state.bank<u.cost?'Faltam moedas'+(u.recipe.some((c,i)=>state.materials[i]<c)?' e gemas':''): 'Faltam gemas')+'</span></div></div>';}
 else if(overlay==='help'){const odds=missionOdds(state);el.innerHTML=head('Chances e regras')+'<div class="overlay-inner help-copy"><div class="odds"><span>Raras '+Math.round(odds.rare*100)+'%</span><span>Douradas '+Math.round(odds.gold*100)+'%</span></div><p>'+ (state.unlocked.includes('questluck')?'Olho de Ouro ativo.':'Olho de Ouro aumenta as chances na Árvore.')+'</p><p>Uma vaga extra em cada nível:</p><div class="slot-levels"><span>30</span><span>60</span><span>90</span><span>120</span></div><p>O prazo só corre na exploração. Progresso continua após a derrota.</p><p>Aceitar e entregar renovam as ofertas. Fechar e abandonar não sorteiam outras.</p><p>Gemas variam por missão e crescem com a raridade e o quadro. Os valores ficam fixos ao aceitar.</p><p>Ofertas indicadas podem trazer um disco ainda não obtido ou Bolota. A chance é por entrega; melhorar o quadro também oferece mais missões raras. Prêmios já obtidos não se repetem.</p></div>';}
 else if(overlay?.kind==='abandon'){const m=missionList(state).find(m=>m.id===overlay.id);if(!m){overlay=null;renderOverlay();return;}el.innerHTML=head('Trocar missão')+'<div class="abandon-view">'+img(families[m.template])+'<h3>'+objective(m)+'</h3><p>'+fmt(m.progress)+'/'+fmt(m.goal)+' · '+time(m)+'</p><p>Abandonar descarta este progresso.<br>As ofertas continuam as mesmas.</p><div class="abandon-actions">'+button('Voltar','id="gm-abandon-back"')+button('Abandonar','data-abandon-mission="'+esc(encodeURIComponent(m.id))+'" data-abandon="'+esc(m.id)+'"','danger')+'</div></div>';}
}
function showOverlay(value){overlay=value;renderOverlay();q('#gm-overlay-close')?.focus({preventScroll:true});remember();}
function closeOverlay(){const old=overlay;overlay=null;renderOverlay();(typeof old==='object'?q('[data-options="'+CSS.escape(old.id)+'"]'):q(old==='upgrade'?'#gm-upgrade-open':'#gm-help'))?.focus({preventScroll:true});remember();}
root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled||busy||disposed)return;onCommand();
 if(b.dataset.area){area=b.dataset.area;renderArea();remember();return;}
 if(b.dataset.page){const kind=b.dataset.page,step=Number(b.dataset.step);if(kind==='active')activePage+=step;else offerPage+=step;renderBoard();q('[data-page="'+kind+'"][data-step="'+(-step)+'"]')?.focus({preventScroll:true});remember();return;}
 if(b.dataset.options){showOverlay({kind:'abandon',id:b.dataset.options});return;}
 if(b.id==='gm-upgrade-open'){showOverlay('upgrade');return;}
 if(b.id==='gm-help'){showOverlay('help');return;}
 if(b.id==='gm-overlay-close'||b.id==='gm-abandon-back'){closeOverlay();return;}
 if(b.dataset.accept){if(event.detail>1)return;busy=true;try{if(acceptMission(state,b.dataset.accept)){area='active';remember();}}finally{busy=false;}return;}
 if(b.dataset.claim){if(event.detail>1)return;busy=true;try{const m=missionList(state).find(m=>m.id===b.dataset.claim);if(!m)return;const reward=missionReward(m),owned=new Set(state.records.owned),pets=new Set(state.homeCollection?.pets||[]);if(claimMission(state,m.id)){const record=REC.RECORDS.find(r=>state.records.owned.includes(r.id)&&!owned.has(r.id));receipt={...reward,record:record?{id:record.id,name:record.name}:null,pets:PET_CATALOG.filter(p=>state.homeCollection?.pets.includes(p.id)&&!pets.has(p.id))};overlay=null;announce('');render();pulse('.receipt .reward img,#gm-bank,.record-found img');q('#gm-receipt-done').focus({preventScroll:true});remember();}}finally{busy=false;}return;}
 if(b.dataset.clear||b.dataset.abandon){if(abandonMission(state,b.dataset.clear||b.dataset.abandon)){overlay=null;announce(b.dataset.clear?'Missão removida.':'Vaga liberada.');render();q('#gm-help').focus({preventScroll:true});remember();}return;}
 if(b.id==='gm-upgrade-confirm'){if(event.detail>1)return;busy=true;try{const slots=missionSlots(state);if(upgradeBuilding(state,'missions')){overlay=null;render();announce(missionSlots(state)>slots?'+1 vaga liberada!':'Quadro melhorado. Novas ofertas disponíveis.');pulse('#gm-level');q('#gm-upgrade-open').focus({preventScroll:true});remember();}}finally{busy=false;}return;}
 if(b.id==='gm-receipt-done'){onReceiptDone();return;}
 if(b.id==='gm-receipt-more'){receipt=null;render();q('#gm-help').focus({preventScroll:true});remember();onBoard();return;}
 if(b.id==='gm-close'){onClose();return;}
});
root.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(overlay)closeOverlay();else onClose();}else if(event.target.matches('[data-area]')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();area=area==='active'?'offers':'active';renderArea();q('#gm-area-'+area).focus({preventScroll:true});remember();}});
render();const resize=new ResizeObserver(()=>{if(disposed)return;const w=root.getBoundingClientRect().width,cap=w>1000?4:2,ac=2;if(cap!==offerCapacity||ac!==activeCapacity){const start=offerPage*offerCapacity,activeStart=activePage*activeCapacity;offerCapacity=cap;activeCapacity=ac;offerPage=Math.floor(start/cap);activePage=Math.floor(activeStart/ac);renderBoard();}});resize.observe(root);
softQuery.addEventListener('change',syncSoft);root.addEventListener('animationend',event=>event.target.classList.remove('pop'));
const unregister=registerMissionPresentation(dialog,{revealOffer(id){if(disposed||overlay||receipt)return null;if(!id)return q('#gm-active-column .section-head');const offers=getOffers(),index=offers.findIndex(m=>m.id===id);if(index<0)return null;const page=Math.floor(index/offerCapacity);if(page!==offerPage||area!=='offers'){offerPage=page;area='offers';renderBoard();renderArea();remember();}const target=all('[data-accept]').find(b=>b.dataset.accept===id);if(target)target.dataset.tutorialRecommended='true';return target||null;}});
q('#gm-close').focus({preventScroll:true});
return()=>{disposed=true;resize.disconnect();softQuery.removeEventListener('change',syncSoft);unregister();root.getAnimations({subtree:true}).forEach(a=>a.cancel());};
}
